package com.resalemarket.listing;

import com.resalemarket.listing.entity.ListingCondition;
import java.time.Instant;
import java.time.OffsetDateTime;
import java.time.ZoneOffset;
import java.util.Collection;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.UUID;
import java.util.stream.Collectors;
import org.springframework.jdbc.core.simple.JdbcClient;
import org.springframework.stereotype.Repository;

/**
 * The public search, in native SQL. JPA cannot use the {@code tsvector} column (it is generated by the database and has no Java
 * type), and one hand-written statement lets the planner use the partial indexes of {@code listings}. The query returns only ids,
 * in order; {@link ListingSearchService} loads the rows.
 *
 * <p>Rules that keep it fast and safe:
 * <ul>
 *   <li><b>Every value is bound</b> ({@code :name}); the SQL text is built from fixed fragments only, never from request text.</li>
 *   <li><b>The status predicate is a literal</b> that is exactly the predicate of the partial indexes ({@code status IN ('ACTIVE',
 *       'RESERVED')}), which is what lets PostgreSQL prove an index applies. A bound parameter would not be provable.</li>
 *   <li>Keyword: full-text on the generated {@code search_vector} (GIN) <b>or</b> the title containing the text (trigram GIN),
 *       so whole words are ranked and part-words such as "iph" still find "iPhone".</li>
 *   <li>Ties are broken by newest and id, so a page boundary never repeats or skips a row.</li>
 * </ul>
 */
@Repository
class ListingSearchRepository {

    /** Must stay identical to the predicate of the partial indexes in V5 (see class comment). */
    private static final String PUBLIC = "l.status IN ('ACTIVE', 'RESERVED')";
    private static final String TS_QUERY = "websearch_to_tsquery('simple', :keyword)";

    private final JdbcClient jdbc;

    ListingSearchRepository(JdbcClient jdbc) {
        this.jdbc = jdbc;
    }

    /** One page of ids in the requested order. */
    List<UUID> ids(ListingSearchCriteria criteria, Collection<UUID> excludedSellers, Instant now, int limit, long offset) {
        Where where = where(criteria, excludedSellers, now);
        String sql = "SELECT l.id FROM listings l WHERE " + where.sql + " ORDER BY " + orderBy(criteria.sort())
                + " LIMIT :limit OFFSET :offset";
        return bind(jdbc.sql(sql), where.params).param("limit", limit).param("offset", offset).query(UUID.class).list();
    }

    long count(ListingSearchCriteria criteria, Collection<UUID> excludedSellers, Instant now) {
        Where where = where(criteria, excludedSellers, now);
        return bind(jdbc.sql("SELECT count(*) FROM listings l WHERE " + where.sql), where.params).query(Long.class).single();
    }

    /** Listings whose promotion is running, newest first. Covered by {@code idx_listings_featured}. */
    List<UUID> featured(Collection<UUID> excludedSellers, Instant now, int limit) {
        Map<String, Object> params = new LinkedHashMap<>();
        String sellers = excludeSellers(excludedSellers, params);
        params.put("now", utc(now));
        String sql = "SELECT l.id FROM listings l WHERE l.is_featured AND l.status = 'ACTIVE'"
                + " AND (l.featured_until IS NULL OR l.featured_until > :now)" + sellers
                + " ORDER BY l.published_at DESC, l.id LIMIT :limit";
        return bind(jdbc.sql(sql), params).param("limit", limit).query(UUID.class).list();
    }

    /** A listing in the "popular" pool, with its seller, so the pool can be filtered per caller without another query. */
    record PopularRow(UUID id, UUID sellerId) {
    }

    /** The most viewed listings that went live since {@code since}, most viewed first. */
    List<PopularRow> mostViewed(Instant since, int limit) {
        String sql = "SELECT l.id, l.seller_id FROM listings l WHERE " + PUBLIC + " AND l.published_at >= :since"
                + " ORDER BY l.view_count DESC, l.published_at DESC, l.id LIMIT :limit";
        return jdbc.sql(sql).param("since", utc(since)).param("limit", limit)
                .query((rs, row) -> new PopularRow(rs.getObject("id", UUID.class), rs.getObject("seller_id", UUID.class)))
                .list();
    }

    /** The newest listings in any of these categories (top-level or sub), leaving out some listings and one seller's own. */
    List<UUID> newestInCategories(
            Collection<Integer> categoryIds,
            Collection<UUID> excludedListings,
            UUID excludedSeller,
            Collection<UUID> excludedSellers,
            int limit) {
        Map<String, Object> params = new LinkedHashMap<>();
        StringBuilder sql = new StringBuilder("SELECT l.id FROM listings l WHERE " + PUBLIC + " AND l.category_id IN (:categoryIds)");
        params.put("categoryIds", categoryIds);
        if (!excludedListings.isEmpty()) {
            sql.append(" AND l.id NOT IN (:excludedListings)");
            params.put("excludedListings", excludedListings);
        }
        if (excludedSeller != null) {
            sql.append(" AND l.seller_id <> :ownSeller");
            params.put("ownSeller", excludedSeller);
        }
        sql.append(excludeSellers(excludedSellers, params));
        sql.append(" ORDER BY l.published_at DESC, l.id LIMIT :limit");
        return bind(jdbc.sql(sql.toString()), params).param("limit", limit).query(UUID.class).list();
    }

    // ------------------------------------------------------------------------------------------------------ SQL pieces

    private record Where(String sql, Map<String, Object> params) {
    }

    private static Where where(ListingSearchCriteria c, Collection<UUID> excludedSellers, Instant now) {
        StringBuilder sql = new StringBuilder(PUBLIC);
        Map<String, Object> params = new LinkedHashMap<>();
        sql.append(excludeSellers(excludedSellers, params));
        if (c.hasKeyword()) {
            sql.append(" AND (l.search_vector @@ ").append(TS_QUERY).append(" OR l.title ILIKE :titlePattern ESCAPE '\\')");
            params.put("keyword", c.keyword());
            params.put("titlePattern", "%" + escapeLike(c.keyword()) + "%");
        }
        equal(sql, params, "l.category_id", "categoryId", c.categoryId());
        equal(sql, params, "l.subcategory_id", "subcategoryId", c.subcategoryId());
        equal(sql, params, "l.province_id", "provinceId", c.provinceId());
        equal(sql, params, "l.district_id", "districtId", c.districtId());
        equal(sql, params, "l.municipality_id", "municipalityId", c.municipalityId());
        if (c.minPrice() != null) {
            sql.append(" AND l.price >= :minPrice");
            params.put("minPrice", c.minPrice());
        }
        if (c.maxPrice() != null) {
            sql.append(" AND l.price <= :maxPrice");
            params.put("maxPrice", c.maxPrice());
        }
        if (!c.conditions().isEmpty()) {
            sql.append(" AND l.item_condition IN (:conditions)");
            params.put("conditions", c.conditions().stream().map(ListingCondition::name).collect(Collectors.toList()));
        }
        if (c.negotiableOnly()) {
            sql.append(" AND l.price_type = 'NEGOTIABLE'");
        }
        if (c.postedWithinDays() != null) {
            sql.append(" AND l.published_at >= :postedSince");
            params.put("postedSince", utc(now.minusSeconds(c.postedWithinDays() * 86_400L)));
        }
        return new Where(sql.toString(), params);
    }

    /** From fixed strings only: the sort is an enum, never request text. */
    private static String orderBy(ListingSort sort) {
        return switch (sort) {
            case RELEVANCE -> "ts_rank(l.search_vector, " + TS_QUERY + ") DESC, l.published_at DESC, l.id";
            case NEWEST -> "l.published_at DESC, l.id";
            case PRICE_ASC -> "l.price ASC, l.published_at DESC, l.id";
            case PRICE_DESC -> "l.price DESC, l.published_at DESC, l.id";
        };
    }

    private static void equal(StringBuilder sql, Map<String, Object> params, String column, String name, Object value) {
        if (value != null) {
            sql.append(" AND ").append(column).append(" = :").append(name);
            params.put(name, value);
        }
    }

    /** Members who may not be seen publicly (suspended or deleted accounts); empty in practice, so usually no clause at all. */
    private static String excludeSellers(Collection<UUID> excludedSellers, Map<String, Object> params) {
        if (excludedSellers.isEmpty()) {
            return "";
        }
        params.put("excludedSellers", excludedSellers);
        return " AND l.seller_id NOT IN (:excludedSellers)";
    }

    /** {@code ILIKE} treats {@code %}, {@code _} and {@code \} as special; the person typed them as plain characters. */
    static String escapeLike(String text) {
        return text.replace("\\", "\\\\").replace("%", "\\%").replace("_", "\\_");
    }

    private static JdbcClient.StatementSpec bind(JdbcClient.StatementSpec statement, Map<String, Object> params) {
        params.forEach(statement::param);
        return statement;
    }

    /** The PostgreSQL driver takes an offset date-time for {@code timestamptz}, not an {@link Instant}. */
    private static OffsetDateTime utc(Instant instant) {
        return OffsetDateTime.ofInstant(instant, ZoneOffset.UTC);
    }
}
